{"function":"() => {
  const orderLinks = Array.from(document.querySelectorAll('a[href*="/orders-v3/order/"]'));

  const orders = orderLinks.map(link => {
    let container = link;
    while (container && container.parentElement && !container.classList.contains('a-box-group') && !container.classList.contains('order-row') && container.tagName !== 'TR') {
      container = container.parentElement;
    }
    const text = container ? container.innerText : link.innerText;

    const dateMatch = text.match(/(\d{4}\/\d{2}\/\d{2})\s+(\d{2}):(\d{2})\s+([A-Z]{3})/);
    const dateStr = dateMatch ? dateMatch[1] : null;
    const hour = dateMatch ? parseInt(dateMatch[2], 10) : null;
    const minute = dateMatch ? parseInt(dateMatch[3], 10) : null;
    const timeStr = dateMatch ? `${dateMatch[2]}:${dateMatch[3]}` : null;
    const tzStr = dateMatch ? dateMatch[4] : null;

    const asinMatch = text.match(/ASIN:\s*([A-Z0-9]{10})/i);
    const asin = asinMatch ? asinMatch[1] : null;

    const skuMatch = text.match(/SKU:\s*([^\n\r]+)/i);
    const sku = skuMatch ? skuMatch[1].trim() : null;

    const amountMatch = text.match(/US\$([0-9\.]+)/);
    const amount = amountMatch ? parseFloat(amountMatch[1]) : 0;

    const qtyMatch = text.match(/数量:\s*(\d+)/);
    const quantity = qtyMatch ? parseInt(qtyMatch[1], 10) : 1;

    const isBusiness = text.includes('企业买家');
    const statusMatch = text.match(/(等待中|未发货|付款完成|已取消|已发货)/);
    const status = statusMatch ? statusMatch[1] : 'Unknown';

    // Calculate Beijing time: PDT + 15 hours
    let bjHour = hour !== null ? (hour + 15) % 24 : null;
    let inUsWestDaytime = (hour >= 10 && hour < 17); // 10:00 - 16:59 PDT -> BJ 01:00 - 07:59

    return {
      orderId: link.innerText.trim(),
      dateStr,
      timeStr,
      hour,
      minute,
      tzStr,
      bjHour,
      inUsWestDaytime,
      asin,
      sku,
      amount,
      quantity,
      isBusiness,
      status
    };
  });

  // Filter 10/28 and 10/29 orders
  const recentOrders = orders.filter(o => o.dateStr === '2026/10/28' || o.dateStr === '2026/10/29');

  // 10/28 stats
  const o28 = recentOrders.filter(o => o.dateStr === '2026/10/28');
  const o28Daytime = o28.filter(o => o.inUsWestDaytime);
  const o28TotalSales = o28.reduce((s, o) => s + o.amount, 0);
  const o28DaytimeSales = o28Daytime.reduce((s, o) => s + o.amount, 0);

  // 10/29 stats (10/29 is today, currently early morning PDT, latest order is ~07:48 PDT)
  const o29 = recentOrders.filter(o => o.dateStr === '2026/10/29');
  const o29TotalSales = o29.reduce((s, o) => s + o.amount, 0);

  // Combined recent
  const totalRecent = recentOrders.length;
  const totalRecentSales = recentOrders.reduce((s, o) => s + o.amount, 0);

  return {
    summary: {
      oct28: {
        totalOrders: o28.length,
        totalSales: parseFloat(o28TotalSales.toFixed(2)),
        daytimeOrders: o28Daytime.length,
        daytimeSales: parseFloat(o28DaytimeSales.toFixed(2)),
        orderRatio: o28.length ? parseFloat(((o28Daytime.length / o28.length) * 100).toFixed(1)) : 0,
        salesRatio: o28TotalSales ? parseFloat(((o28DaytimeSales / o28TotalSales) * 100).toFixed(1)) : 0
      },
      oct29Today: {
        totalOrders: o29.length,
        totalSales: parseFloat(o29TotalSales.toFixed(2)),
        latestPdtTime: o29[0]?.timeStr,
        note: "10/29 美西目前刚过早晨 07:48，美西白天（10:00-17:00，对应北京时间 01:00-08:00）尚未开始，目前订单均为美西清晨及夜间单"
      }
    },
    oct28DaytimeOrderList: o28Daytime.map(o => ({
      orderId: o.orderId,
      timePdt: `${o.dateStr} ${o.timeStr} PDT`,
      timeBj: `北京时间 ${o.bjHour}:${o.minute < 10 ? '0' : ''}${o.minute}`,
      sku: o.sku,
      amount: o.amount,
      qty: o.quantity,
      isBusiness: o.isBusiness
    })),
    oct28AllOrdersSample: o28.slice(0, 10).map(o => ({
      orderId: o.orderId,
      time: o.timeStr,
      inDaytime: o.inUsWestDaytime,
      sku: o.sku,
      amount: o.amount
    }))
  };
}","pageId":7,"toolSummary":"Analyze order distribution by time"}

